// Render all analysed applications as an HTML dashboard (best match first)
const q = $('Dashboard URL').first().json.query || {};
const esc = v => String(v ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

let rows = $('Get Applications').all().map(i => i.json).filter(r => r.application_id);
// latest email per application (email_log may be empty or missing)
const lastMail = {};
for (const m of $('Get Email Log').all().map(i => i.json).filter(m => m.application_id)) {
  if (!lastMail[m.application_id] || String(m.sent_at) > String(lastMail[m.application_id].sent_at)) lastMail[m.application_id] = m;
}
const mailBadge = id => {
  const m = lastMail[id];
  if (!m) return '';
  const c = m.status !== 'Sent' ? '#dc2626' : m.email_type === 'Rejection' ? '#6b7280' : '#16a34a';
  return '<div class="mail" style="color:' + c + '">' + (m.status === 'Sent' ? '\u2709 ' + esc(m.email_type) + ' sent' : '\u26a0 ' + esc(m.email_type) + ' failed') + '<br><small>' + esc(String(m.sent_at || '').slice(0, 16).replace('T', ' ')) + '</small></div>';
};
if (q.job_id) rows = rows.filter(r => r.job_id === q.job_id);
rows.sort((a, b) => (Number(b.match_score) || 0) - (Number(a.match_score) || 0));

const pill = rec => {
  const c = { Shortlist: '#16a34a', Maybe: '#d97706', Reject: '#dc2626' }[rec] || '#6b7280';
  return '<span class="pill" style="background:' + c + '">' + esc(rec || '-') + '</span>';
};
const bar = s => {
  const n = Math.max(0, Math.min(100, Number(s) || 0));
  const c = n >= 75 ? '#16a34a' : n >= 50 ? '#d97706' : '#dc2626';
  return '<div class="score"><b>' + n + '</b><div class="track"><div style="width:' + n + '%;background:' + c + '"></div></div></div>';
};
const count = rec => rows.filter(r => r.recommendation === rec).length;

const body = rows.length ? rows.map(r =>
  '<tr>' +
  '<td><b>' + esc(r.candidate_name) + '</b><br><small>' + esc(r.email) + (r.phone ? ' · ' + esc(r.phone) : '') + '</small>' +
    (r.college ? '<br><small>' + esc(r.college) + '</small>' : '') + '</td>' +
  '<td>' + esc(r.job_title) + '<br><small>' + esc(r.job_id) + '</small></td>' +
  '<td>' + bar(r.match_score) + '</td>' +
  '<td>' + pill(r.recommendation) + '</td>' +
  '<td><small><b>Has:</b> ' + esc(r.matched_skills || '-') + '<br><b>Missing:</b> ' + esc(r.missing_skills || '-') + '</small></td>' +
  '<td><small>' + esc(r.ai_summary) + '</small></td>' +
  '<td><small>' + esc((r.submitted_at || '').slice(0, 16).replace('T', ' ')) + '<br>' + esc(r.resume_file) + '</small></td>' +
  '<td class="act"><a class="btn" target="_blank" href="/webhook/resume?id=' + encodeURIComponent(r.application_id) + '">View</a>' +
    '<a class="btn ghost" href="/webhook/resume?id=' + encodeURIComponent(r.application_id) + '&dl=1">Download</a>' +
    '<div class="decide"><form class="inl" method="POST" action="/webhook/send-mail">' +
      '<input type="hidden" name="id" value="' + esc(r.application_id) + '"><input type="hidden" name="type" value="rejection">' +
      '<button class="btn rej" type="submit">Reject</button></form>' +
    '<a class="btn sel" target="_blank" href="/webhook/compose-mail?id=' + encodeURIComponent(r.application_id) + '">Select</a></div>' + mailBadge(r.application_id) + '</td>' +
  '</tr>'
).join('') : '<tr><td colspan="8" class="empty">No applications yet. Submit one through the apply form.</td></tr>';

const page = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' +
'<title>Resume Analyzer Results</title><style>' +
'body{font-family:system-ui,Segoe UI,sans-serif;margin:0;background:#f6f7f9;color:#111}' +
'header{padding:20px 24px;background:#111827;color:#fff}h1{margin:0;font-size:20px}' +
'.stats{display:flex;gap:12px;padding:16px 24px;flex-wrap:wrap}.stat{background:#fff;border-radius:10px;padding:12px 16px;box-shadow:0 1px 2px #0001;min-width:110px}' +
'.stat b{display:block;font-size:22px}.wrap{padding:0 24px 24px;overflow-x:auto}' +
'table{width:100%;border-collapse:collapse;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 1px 2px #0001}' +
'th,td{padding:10px 12px;text-align:left;vertical-align:top;border-bottom:1px solid #eee;font-size:14px}th{background:#f3f4f6;font-size:12px;text-transform:uppercase;color:#555}' +
'small{color:#555}.pill{color:#fff;padding:3px 10px;border-radius:999px;font-size:12px;font-weight:600}' +
'.score{min-width:110px}.track{height:6px;background:#eee;border-radius:3px;margin-top:4px}.track div{height:6px;border-radius:3px}.empty{text-align:center;padding:40px;color:#777}' +
'.act{white-space:nowrap}.btn{display:inline-block;padding:5px 10px;margin:0 4px 4px 0;border-radius:6px;background:#111827;color:#fff;text-decoration:none;font-size:12px;font-weight:600}' +
'.inl{display:inline;margin:0}button.btn{border:0;cursor:pointer;font-family:inherit;line-height:normal}.btn.rej{background:#dc2626}.btn.sel{background:#16a34a}.decide{margin-top:2px}' +
'.btn.mailbtn{background:#2563eb}.mail{font-size:12px;font-weight:600;margin-top:2px}' +
'.btn.ghost{background:#fff;color:#111827;border:1px solid #d1d5db}' +
'</style></head><body><header><h1>Resume Analyzer — Results' + (q.job_id ? ' · ' + esc(q.job_id) : '') + '</h1></header>' +
'<div class="stats"><div class="stat"><b>' + rows.length + '</b>Applications</div>' +
'<div class="stat"><b style="color:#16a34a">' + count('Shortlist') + '</b>Shortlist</div>' +
'<div class="stat"><b style="color:#d97706">' + count('Maybe') + '</b>Maybe</div>' +
'<div class="stat"><b style="color:#dc2626">' + count('Reject') + '</b>Reject</div></div>' +
'<div class="wrap"><table><thead><tr><th>Candidate</th><th>Job</th><th>Score</th><th>Verdict</th><th>Skills</th><th>AI summary</th><th>Submitted</th><th>Resume / Decision</th></tr></thead>' +
'<tbody>' + body + '</tbody></table></div></body></html>';

return [{ json: { html: page } }];

// Only accept real application IDs (blocks path tricks like ../)
const id = String($json.query?.id || '').trim();
const valid = /^APP-[A-Z0-9]+$/.test(id);
return [{ json: { id, valid, pattern: valid ? '/home/node/.n8n-files/resumes/' + id + '.*' : '' } }];
